mapper.select:
SELECT * from player_result_activityid${l} pra RIGHT JOIN t_free_game_result tfr on pra.activity_id = tfr.activity_id
    WHERE pra.player_id=#{userId}

        and pra.group_id = #{groupId}


        and tfr.`level` = #{level}


        and pra.type = #{type}

    order by tfr.end_date desc
    limit ${startPage},${pageSize}

SELECT count(1) from player_result_activityid${l} pra RIGHT JOIN t_free_game_result tfr on pra.activity_id = tfr.activity_id
WHERE pra.player_id=#{userId}

    and pra.group_id = #{groupId}


    and tfr.`level` = #{level}


    and pra.type = #{type}
